mapper.select:
SELECT COUNT(0) FROM ( SELECT 1 FROM `t_statistics` WHERE `project_id` = #{projectId} GROUP BY
`tag` `ip`
) AS `t_count`

SELECT COUNT(0) FROM ( SELECT 1 FROM `t_statistics` WHERE `project_id` = #{projectId} AND `createtime` >= CURDATE() GROUP BY
`tag` `ip`
) AS `t_count`

SELECT COUNT(0) FROM ( SELECT 1 FROM `t_statistics` WHERE `project_id` = #{projectId} AND `createtime` >= DATE_SUB(CURDATE(), INTERVAL 1 DAY) AND `createtime` < CURDATE() GROUP BY
`tag` `ip`
) AS `t_count`
